mapper.select:


    formColumn.deleted_flag = 'N'
    and formColumn.department_id = #{departmentId}
    and formColumn.organization_id =
        #{organizationId}

    and formColumn.remark = #{remark}
    and formColumn.title = #{title}
    and formColumn.status = #{status}
    and formColumn.form_id = #{formId}
    and formColumn.filed_code = #{filedCode}
    and formColumn.component_id = #{componentId}
    and formColumn.filed_name like concat('%', #{filedName},
        '%')

    and formColumn.filed_type = #{filedType}
    and formColumn.length = #{length}
    and formColumn.scale = #{scale}
    and formColumn.sort = #{sort}
    and formColumn.default_value = #{defaultValue}
    and formColumn.show_list = #{showList}
    and formColumn.show_query = #{showQuery}

        and

            (
            formColumn.remark like concat('%', #{item}, '%')
            or formColumn.title like concat('%', #{item}, '%')
            )



order by formColumn.sort asc


left join dynamic_form as form on form.id = formColumn.form_id

    formColumn.deleted_flag = 'N' and form.table_code = #{tableCode}

order by formColumn.sort asc
